function gcd(a,b){a=Math.abs(Math.floor(a));b=Math.abs(Math.floor(b));while(b){var t=b;b=a%b;a=t;}return a;}
function gcdMany(arr){var g=arr[0];for(var i=1;i<arr.length;i++)g=gcd(g,arr[i]);return g;}
function lcm(a,b){if(a===0&&b===0)return 0;return Math.abs(a*b)/gcd(a,b);}
function lcmMany(arr){var l=arr[0];for(var i=1;i<arr.length;i++)l=lcm(l,arr[i]);return l;}
function factorize(n){n=Math.floor(Math.abs(n));if(n<2)return [];var f=[];var d=2;while(d*d<=n){var c=0;while(n%d===0){c++;n=n/d;}if(c)f.push([d,c]);d++;}if(n>1)f.push([n,1]);return f;}
function isCoprime(a,b){return gcd(a,b)===1;}
